"""Fullscreen Android activity, implemented in Python. Java glue is generated by Chaquopy."""
from pathlib import Path
import json
import threading
import time
from urllib.request import Request,urlopen

from java import static_proxy,dynamic_proxy,Override,jvoid,jbyte,jarray
from java.lang import Runnable
from android.app import Activity,AlertDialog
from android.os import Bundle
from android.view import View,Gravity,MotionEvent,WindowManager
from android.widget import FrameLayout,LinearLayout,GridLayout,TextView,Button,ImageView,EditText
from android.graphics import BitmapFactory,Color
from android.graphics.drawable import GradientDrawable
from android.content import DialogInterface


class Task(dynamic_proxy(Runnable)):
    def __init__(self,function): super().__init__();self.function=function
    def run(self): self.function()


class Click(dynamic_proxy(View.OnClickListener)):
    def __init__(self,function): super().__init__();self.function=function
    def onClick(self,_view): self.function()


class Confirm(dynamic_proxy(DialogInterface.OnClickListener)):
    def __init__(self,function): super().__init__();self.function=function
    def onClick(self,_dialog,_which): self.function()


class Touch(dynamic_proxy(View.OnTouchListener)):
    def __init__(self,press,release):
        super().__init__();self.press=press;self.release=release
    def onTouch(self,view,event):
        action=event.getActionMasked()
        if action==MotionEvent.ACTION_DOWN:
            view.setPressed(True)
            self.press()
        elif action in (MotionEvent.ACTION_UP,MotionEvent.ACTION_CANCEL):
            view.setPressed(False)
            self.release()
            if action==MotionEvent.ACTION_UP: view.performClick()
        elif action==MotionEvent.ACTION_MOVE:
            if not (0<=event.getX()<view.getWidth() and 0<=event.getY()<view.getHeight()):
                view.setPressed(False)
                self.release()
        return True


class MainActivity(static_proxy(Activity)):
    @Override(jvoid,[Bundle])
    def onCreate(self,bundle):
        Activity.onCreate(self,bundle)
        self.alive=True
        self.connection=threading.Event()
        self.direction='stop'
        self.grip='stop'
        self.last_frame=0.
        self.network=None
        self.listeners=[]
        self.detector=None
        self.speed=.35
        self.getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN|WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        self.getWindow().getDecorView().setSystemUiVisibility(5894)
        self.folder=Path(str(self.getFilesDir()))/'models'
        self.folder.mkdir(exist_ok=True)
        for filename in ('net.onnx','model.json'):
            self.copy_asset('models/'+filename,self.folder/filename)
        config_path=Path(str(self.getFilesDir()))/'connection.json'
        self.copy_asset('connection.json',config_path)
        self.config=json.loads(config_path.read_text())
        self.preferences=self.getSharedPreferences('netrobot',0)
        self.server=str(self.preferences.getString('server',self.config['server'])).rstrip('/')
        self.token=self.config['token']
        self.build_screen()
        self.start()

    def dp(self,value):
        return round(value*self.getResources().getDisplayMetrics().density)

    def copy_asset(self,name,destination):
        source=self.getAssets().open(name)
        buffer=jarray(jbyte)(65536)
        with Path(destination).open('wb') as output:
            while True:
                count=source.read(buffer)
                if count<0: break
                output.write(bytes(buffer)[:count])
        source.close()

    def panel(self,view,alpha=165):
        background=GradientDrawable()
        background.setColor(Color.argb(alpha,15,25,40))
        background.setCornerRadius(float(self.dp(18)))
        background.setStroke(self.dp(1),Color.argb(120,165,200,220))
        view.setBackground(background)

    def text(self,value,size=16):
        view=TextView(self)
        view.setText(value)
        view.setTextColor(Color.WHITE)
        view.setTextSize(float(size))
        view.setGravity(Gravity.CENTER_VERTICAL)
        return view

    def button(self,text,press=None,release=None):
        view=Button(self)
        view.setText(text)
        view.setTextColor(Color.WHITE)
        view.setTextSize(18.)
        view.setAllCaps(False)
        view.setMinWidth(0)
        view.setMinimumWidth(0)
        view.setMinHeight(0)
        view.setMinimumHeight(0)
        self.panel(view,185)
        if press:
            listener=Touch(press,release or (lambda:None))
            view.setOnTouchListener(listener)
            self.listeners.append(listener)
        return view

    def build_screen(self):
        root=FrameLayout(self)
        root.setBackgroundColor(Color.BLACK)
        self.video=ImageView(self)
        self.video.setScaleType(ImageView.ScaleType.CENTER_CROP)
        root.addView(self.video,FrameLayout.LayoutParams(-1,-1))
        top=LinearLayout(self)
        top.setOrientation(LinearLayout.HORIZONTAL)
        top.setPadding(self.dp(12),0,self.dp(8),0)
        self.panel(top,160)
        self.status=self.text('카메라 연결 중 · 그물 감지는 휴대폰에서 실행',15)
        top.addView(self.status,LinearLayout.LayoutParams(0,-1,1.))
        settings=self.button('연결 설정')
        listener=Click(self.settings)
        settings.setOnClickListener(listener)
        self.listeners.append(listener)
        top.addView(settings,LinearLayout.LayoutParams(self.dp(110),-1))
        params=FrameLayout.LayoutParams(-1,self.dp(48),Gravity.TOP)
        params.setMargins(self.dp(12),self.dp(8),self.dp(12),0)
        root.addView(top,params)
        self.direction_keys=GridLayout(self)
        self.direction_keys.setColumnCount(3)
        self.direction_keys.setRowCount(3)
        for text,direction in [('',None),('▲','forward'),('',None),('◀','left'),('정지','stop'),('▶','right'),('',None),('▼','backward'),('',None)]:
            key=self.text('') if direction is None else self.button(text,lambda d=direction:self.set_direction(d),lambda:self.set_direction('stop'))
            key_params=GridLayout.LayoutParams()
            key_params.width=self.dp(60)
            key_params.height=self.dp(54)
            self.direction_keys.addView(key,key_params)
        params=FrameLayout.LayoutParams(self.dp(180),self.dp(162),Gravity.LEFT|Gravity.BOTTOM)
        params.setMargins(self.dp(18),0,0,self.dp(16))
        root.addView(self.direction_keys,params)
        gripper=LinearLayout(self)
        gripper.setOrientation(LinearLayout.VERTICAL)
        self.grip_label=self.text('집게 · 누르는 동안 동작',13)
        gripper.addView(self.grip_label,LinearLayout.LayoutParams(-1,self.dp(28)))
        for caption,action in [('집게 닫기','close'),('집게 열기','open')]:
            key=self.button(caption,lambda a=action:self.set_grip(a),lambda:self.set_grip('stop'))
            gripper.addView(key,LinearLayout.LayoutParams(-1,self.dp(58)))
        params=FrameLayout.LayoutParams(self.dp(158),self.dp(144),Gravity.RIGHT|Gravity.BOTTOM)
        params.setMargins(0,0,self.dp(18),self.dp(16))
        root.addView(gripper,params)
        self.setContentView(root)

    def settings(self):
        self.stop()
        field=EditText(self)
        field.setSingleLine(True)
        field.setText(self.server)
        def confirm():
            self.server=str(field.getText()).strip().rstrip('/')
            self.preferences.edit().putString('server',self.server).apply()
            self.start()
        listener=Confirm(confirm)
        self.listeners.append(listener)
        dialog=AlertDialog.Builder(self).setTitle('노트북 주소 · 같은 Wi-Fi에 연결').setView(field).setPositiveButton('연결',listener).setNegativeButton('취소',None).create()
        dialog.show()

    def message(self,value):
        if self.alive:
            self.runOnUiThread(Task(lambda:self.status.setText(value)))

    def set_direction(self,direction):
        if direction!='stop' and (not self.connection.is_set() or time.monotonic()-self.last_frame>1.):
            self.message('영상 연결을 확인한 뒤 조종하세요.')
            direction='stop'
        self.direction=direction

    def set_grip(self,action):
        if action!='stop' and (not self.connection.is_set() or time.monotonic()-self.last_frame>1.):
            self.message('영상 연결을 확인한 뒤 집게를 조종하세요.')
            action='stop'
        self.grip=action

    def start(self):
        if self.network and self.network.is_alive():
            self.message('이전 연결을 정리하고 있습니다. 연결 설정에서 다시 눌러주세요.')
            return
        if not self.server.startswith('http://'):
            self.message('연결 설정에 http://노트북IP:8765를 입력하세요.')
            return
        self.connection=threading.Event()
        self.connection.set()
        self.direction=self.grip='stop'
        self.last_frame=0
        self.network=threading.Thread(target=self.frames,args=(self.connection,self.server),daemon=True)
        self.network.start()
        threading.Thread(target=self.controls,args=(self.connection,self.server),daemon=True).start()

    def request(self,server,path,payload=None,timeout=2):
        headers={'X-Control-Token':self.token}
        data=None
        if payload is not None:
            headers['Content-Type']='application/json'
            data=json.dumps(payload).encode()
        with urlopen(Request(server+path,data=data,headers=headers),timeout=timeout) as response:
            return response.read(),response.headers

    def frames(self,connection,server):
        from onnx_android import Detector,draw
        try:
            if self.detector is None:
                self.message('휴대폰 YOLO 모델 준비 중…')
                self.detector=Detector(self.folder)
        except Exception as exc:
            self.message('모델 준비 오류: '+str(exc))
            connection.clear()
            return
        previous=-1
        while self.alive and connection.is_set():
            try:
                data,headers=self.request(server,'/frame.jpg')
                sequence=int(headers.get('X-Frame-Sequence','0'))
                if sequence==previous:
                    time.sleep(.03)
                    continue
                previous=sequence
                bitmap=BitmapFactory.decodeByteArray(jarray(jbyte)(data),0,len(data))
                if bitmap is None: raise ValueError('잘못된 카메라 사진')
                self.last_frame=time.monotonic()
                start=time.monotonic()
                results=self.detector.predict(bitmap)
                image=draw(bitmap,results)
                bitmap.recycle()
                elapsed=(time.monotonic()-start)*1000
                found=' / '.join(f"그물 {r['score']:.0%}" for r in results) or '그물 없음'
                if not self.detector.info.get('trained_on_net',False): found='일반 모델 시험(그물 미학습)'
                status=f'{found} · {elapsed:.0f}ms · '+getattr(self,'motor_mode','모의 조종')
                def update(image=image,status=status):
                    if self.alive:
                        self.video.setImageBitmap(image)
                        self.status.setText(status)
                self.runOnUiThread(Task(update))
            except Exception as exc:
                self.direction=self.grip='stop'
                self.message('영상 연결 끊김 · 정지 · '+str(exc)[:90])
                time.sleep(.3)

    def controls(self,connection,server):
        while self.alive and connection.is_set():
            if time.monotonic()-self.last_frame>1.:
                self.direction=self.grip='stop'
            try:
                data,_=self.request(server,'/control',{'direction':self.direction,'speed':self.speed},.6)
                state=json.loads(data)
                self.motor_mode='모의 조종' if state.get('simulated',True) else 'Arduino 연결'
                self.request(server,'/gripper',{'action':self.grip},.6)
            except Exception:
                self.direction=self.grip='stop'
            time.sleep(.1)
        for path,payload in [('/control',{'direction':'stop','speed':0}),('/gripper',{'action':'stop'})]:
            try: self.request(server,path,payload,.6)
            except Exception: pass

    def stop(self):
        self.direction=self.grip='stop'
        self.connection.clear()

    @Override(jvoid,[])
    def onPause(self):
        self.stop()
        Activity.onPause(self)

    @Override(jvoid,[])
    def onDestroy(self):
        self.stop()
        self.alive=False
        Activity.onDestroy(self)
